#include <stdio.h>
int rodCut(int p[], int n) {
    int dp[n+1];
    dp[0]=0;
    for (int i=1; i<=n; i++) {
        dp[i]=0;
        for (int j=1; j<=i; j++)if (p[j-1]+dp[i-j]>dp[i])dp[i]=p[j-1]+dp[i-j];
    }
    return dp[n];
}
